-- 2026-11-11: the marketing email copy no longer uses dashes ("–"). Rewrites only the seeded sentences,
-- so text an admin has changed is left alone. Idempotent.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

